// src/logic/core/combat.ts
import { CardInstance, Player } from "../../core/types.js";
import { state } from "../../core/gameState.js";
import { logEvent } from "../../core/logger.js";

import { fireTrigger } from "./triggers.js";
import { recordEvent } from "../../core/debugTimeline.js";
import { clearCantAttack } from "./keywords/remove.js";




// Imported from JS still
import { applyLeaderDamage, handleHealLeader } from "../effects/leader.js";
import { destroyTarget } from "../effects/ops/destroy/index.js";
import { cleanupDead } from "./cleanup.js";
import { adapter } from "../../core/adapter.js";
import { dealDamage, popBarrier } from "./barrier.js";
import { doAction } from "../../core/history.js";


/* ------------------------------- helpers ------------------------------- */

function boardFor(player: Player): CardInstance[] { return player === "blue" ? state.blueBoard : state.redBoard; }
function leaderHPKey(player: Player): "blueHP" | "redHP" { return player === "blue" ? "blueHP" : "redHP"; }
function enemyOf(player: Player): Player { return player === "blue" ? "red" : "blue"; }
function hasWardOn(board: CardInstance[]) { return board.some(c => c && c.type === "Follower" && c.hasWard); }
function canTargetFollower(defender: CardInstance, defenderBoard: CardInstance[]) {
    if (!defender || defender.type !== "Follower") return false;
    if (defender.hasAmbush) return false;
    if (defender.keywordState?.hasIntimidate || (defender as any).hasIntimidate) return false; // Check both for safety/migration
    if (hasWardOn(defenderBoard) && !defender.hasWard) return false;
    return true;
}
function effectiveAtk(card: CardInstance) {
    return Math.max(0, parseInt(card?.attack as any, 10) || 0);
}

/* attack counter + flags */

function spendAttack(attacker: CardInstance) {
    if (attacker.attacks_left == null) {
        const per = Number.isFinite(attacker.attacks_per_turn) ? (attacker.attacks_per_turn as number) : 1;
        attacker.attacks_left = per;
    }

    // mark: someone attacked this turn (even if they die later)
    const ownerIsBlue = (state.blueBoard || []).includes(attacker);
    const owner = ownerIsBlue ? "blue" : "red";
    if (owner === "blue") state.blueAnyAllyAttackedThisTurn = true;
    else state.redAnyAllyAttackedThisTurn = true;

    attacker.attacks_used_this_turn = (attacker.attacks_used_this_turn ?? 0) + 1;
    const left = (attacker.attacks_left ?? 1) - 1;
    attacker.attacks_left = Math.max(0, left);
    attacker.hasAttacked = attacker.attacks_left <= 0;
}


function isAttackForbidden(card: CardInstance) {
    if (!card) return false;
    const ks = card.keywordState;
    // Fix: Do NOT clear it here. 
    // Clearing happens in turns.ts at End of Turn. 
    // Clearing here causes it to vanish the moment the owner tries to attack.
    return !!(ks?.cantAttack || ks?.cantAttackFollowers || ks?.cantAttackLeaders);
}

function recomputeAttackFlags(card: CardInstance) {
    const eligible = !!(card.hasStorm || !card.justPlayed || card.hasRush);
    const swingsLeft = ((card as any).attacks_left ?? 0) > 0;
    // Fix: Check isAttackForbidden
    const forbidden = isAttackForbidden(card);
    (card as any).can_attack = eligible && swingsLeft && !forbidden;
    card.isRush = !!(card.justPlayed && card.hasRush && !card.hasStorm);
}
function stripAmbushOnSelfAttack(attacker: CardInstance) { if (attacker.hasAmbush) attacker.hasAmbush = false; }

/** Check if a card currently has a trigger for a given event in a given zone (default: board). */
function hasCardTrigger(card: CardInstance, eventName: string, source = "board") {
    return Array.isArray((card as any)?.triggers)
        && (card as any).triggers.some((t: any) => t.event === eventName && t.source === source);
}

/* ------------------------ superevolve convenience checks ------------------------ */
function isInvincibleOnAttack(attacker: CardInstance) { return attacker?.evoType === "super" || !!attacker.keywordState?.isInvincibleOnAttack; }
function hasPiercingOne(attacker: CardInstance) { return attacker?.evoType === "super" || !!attacker.keywordState?.hasPiercing; }

/* --------------------------- follower vs follower --------------------------- */

function _attackFollowerCore(attackerIdx: number, defenderIdx: number, attackerPlayer: Player, defenderPlayer: Player) {
    const attackerBoard = boardFor(attackerPlayer);
    const defenderBoard = boardFor(defenderPlayer);

    const attacker = attackerBoard[attackerIdx];
    const defender = defenderBoard[defenderIdx];

    // Basic guards
    if (!attacker || !defender) return;
    if (attacker.type !== "Follower" || defender.type !== "Follower") return;
    if (!(attacker as any).can_attack || ((attacker as any).attacks_left ?? 1) <= 0) return;
    if (isAttackForbidden(attacker)) return; // Checks keywordState inside
    if (!canTargetFollower(defender, defenderBoard)) return;

    // Ambush breaks on own attack
    stripAmbushOnSelfAttack(attacker);

    // Battle-start style hooks
    fireTrigger("clash", attackerPlayer, { attacker, defender });
    fireTrigger("clash", defenderPlayer, { attacker, defender });

    // Generic strike payloads (e.g., Jeno-style effects) resolve before damage
    fireTrigger("strike", attackerPlayer, { attacker, defender });

    // Ensure swing counter exists
    if ((attacker as any).attacks_left == null) {
        (attacker as any).attacks_left = Number.isFinite((attacker as any).attacks_per_turn)
            ? (attacker as any).attacks_per_turn
            : 1;
    }

    // Normalize stats after pre-damage triggers
    attacker.attack = parseInt(attacker.attack as any) || 0;
    attacker.defense = parseInt(attacker.defense as any) || 0;
    defender.attack = parseInt(defender.attack as any) || 0;
    defender.defense = parseInt(defender.defense as any) || 0;

    const atkDmg = effectiveAtk(attacker);
    const defDmg = effectiveAtk(defender);

    const attackerHasBane = !!attacker.hasBane;
    const defenderHasBane = !!defender.hasBane;
    const attackerHasDrain = !!attacker.hasDrain;
    /* const defenderHasDrain = !!defender.hasDrain; */ // unused variable

    // --- Follower Strike: BEFORE damage (no first-strike) ---
    if (hasCardTrigger(attacker, "follower_strike", "board")) {
        fireTrigger("follower_strike", attackerPlayer, { attacker, defender });

        // IMMEDIATE CLEANUP so 0-DEF units vanish before damage exchange
        cleanupDead();
        adapter.render();

        // If the defender was removed or died due to follower_strike, award piercing now.
        const stillThere = defenderBoard[defenderIdx];
        if (!stillThere || stillThere !== defender || (defender.defense as any) <= 0) {
            if (hasPiercingOne(attacker)) {
                const hpKey = leaderHPKey(defenderPlayer);
                state[hpKey] = Math.max(0, state[hpKey] - 1);
            }
            spendAttack(attacker);
            recomputeAttackFlags(attacker);
            adapter.render();
            return;
        }

        // Re-normalize in case effects changed stats
        attacker.attack = parseInt(attacker.attack as any) || 0;
        attacker.defense = parseInt(attacker.defense as any) || 0;
        defender.attack = parseInt(defender.attack as any) || 0;
        defender.defense = parseInt(defender.defense as any) || 0;
    }
    // For now, assuming UI filtered it.

    recordEvent({ type: "attack", payload: { attacker: attacker.name, defender: defender.name } });

    attacker.hasAttacked = true;
    logEvent("attack", { attacker: attacker.name, defender: defender?.name, atkDmg, defDmg });

    // --- Simultaneous damage exchange ---
    let dealtToDef = 0;
    let dealtToAtk = 0;

    // Attacker deals damage to defender
    const dmgResultDef = dealDamage(defender, atkDmg, attacker);
    dealtToDef = dmgResultDef.damage;

    // Bane triggers if damage was dealt OR a barrier was popped (which means it "hit")
    if (attackerHasBane && (dealtToDef > 0 || dmgResultDef.barrierPopped)) {
        // Route through centralized destroy (respects cannotBeDestroyed & super-protect)
        destroyTarget(defender, defenderPlayer, "bane");
        logEvent("baneDestroy", { killer: attacker.name, victim: defender.name });
    }

    // Defender deals back, unless attacker is invincible on attack this swing
    if (!isInvincibleOnAttack(attacker)) {
        const dmgResultAtk = dealDamage(attacker, defDmg, defender);
        dealtToAtk = dmgResultAtk.damage;

        if (defenderHasBane && (dealtToAtk > 0 || dmgResultAtk.barrierPopped)) {
            destroyTarget(attacker, attackerPlayer, "bane");
            logEvent("baneDestroy", { killer: defender.name, victim: attacker.name });
        }
    } else if (attacker.keywordState?.hasBarrier || (attacker as any).hasBarrier) {
        popBarrier(attacker, "invincible_simul_zero");
    }

    // Drain (leaders heal based on actual damage dealt)
    if (attackerHasDrain && dealtToDef > 0) {
        handleHealLeader(attackerPlayer, { op: "heal", amount: dealtToDef } as any);
        logEvent("drainHeal", { player: attackerPlayer, amount: dealtToDef, source: attacker.name });
    }


    // --- Piercing: if defender will die from this exchange, ping enemy leader for 1 ---
    if (hasPiercingOne(attacker) && (parseInt(defender.defense as any) || 0) <= 0) {
        const hpKey = leaderHPKey(defenderPlayer);
        state[hpKey] = Math.max(0, state[hpKey] - 1);
        logEvent("piercingPing", { attacker: attacker.name, targetLeader: defenderPlayer, amount: 1 });
    }

    // Spend the swing, refresh flags, clean, render
    spendAttack(attacker);
    recomputeAttackFlags(attacker);
    cleanupDead();
    adapter.render();
}

export function attackFollower(attackerIdx: number, defenderIdx: number, attackerPlayer: Player, defenderPlayer: Player) {
    const meta = { attackerIdx, defenderIdx, attackerPlayer, defenderPlayer };
    return doAction("Attack Follower", () =>
        _attackFollowerCore(attackerIdx, defenderIdx, attackerPlayer, defenderPlayer),
        meta,
        { autoRender: false }
    );
}

/* ----------------------------- follower -> leader ---------------------------- */

function _attackLeaderCore(attackerIdx: number, attackerPlayer: Player, defenderPlayer: Player) {
    // define first, then log
    const attackerBoard = boardFor(attackerPlayer);
    const defenderBoard = boardFor(defenderPlayer); // used for ward check
    const attacker = attackerBoard[attackerIdx];

    logEvent("attackLeader", {
        attacker: attacker?.name,
        attackerUid: attacker?.uid,
        attackerPlayer,
    });

    if (!attacker || attacker.type !== "Follower") return;

    // Rush can't hit leader on play turn
    if (attacker.hasRush && attacker.justPlayed && !attacker.hasStorm) return;

    if (!(attacker as any).can_attack || ((attacker as any).attacks_left ?? 1) <= 0) return;
    if (isAttackForbidden(attacker)) return;
    if (hasWardOn(defenderBoard)) return;

    stripAmbushOnSelfAttack(attacker);

    if ((attacker as any).attacks_left == null) {
        (attacker as any).attacks_left = Number.isFinite((attacker as any).attacks_per_turn)
            ? (attacker as any).attacks_per_turn
            : 1;
    }

    // Strike payloads also fire when attacking leader (Jeno barrier, etc.)
    fireTrigger("strike", attackerPlayer, { attacker });

    attacker.attack = parseInt(attacker.attack as any) || 0;
    attacker.defense = parseInt(attacker.defense as any) || 0;

    // Fire generic defender trigger (pre-damage)
    // Synchronous execution ensures any debuffs (e.g. Lu Woh) apply before effectiveAtk()
    fireTrigger("leader_attacked", defenderPlayer, { attacker });

    const damage = effectiveAtk(attacker);
    applyLeaderDamage(defenderPlayer, damage);

    if ((attacker as any).hasDrain && damage > 0) {
        handleHealLeader(attackerPlayer, { op: "heal", amount: damage } as any);
        logEvent("drainHeal", { player: attackerPlayer, amount: damage, source: attacker.name });
    }

    spendAttack(attacker);
    recomputeAttackFlags(attacker);
    adapter.render();
}

export function attackLeader(attackerIdx: number, attackerPlayer: Player, defenderPlayer: Player) {
    const meta = { attackerIdx, attackerPlayer, defenderPlayer };
    return doAction("Attack Leader", () =>
        _attackLeaderCore(attackerIdx, attackerPlayer, defenderPlayer),
        meta,
        { autoRender: false }
    );
}

/* ------------------------------ drag-drop hook ------------------------------ */
export function handleDropOnLeader(attackerIdx: number, attackerPlayer: Player) {
    return attackLeader(attackerIdx, attackerPlayer, enemyOf(attackerPlayer));
}

import { registerOp } from "../registry.js";
// import { state } from "../../../../core/gameState.js";
import { getPool, highlightSelectable } from "../../targeting.js";
import { setPendingTarget } from "../../pendingTarget/index.js";
import {
    handleStat, handleComboRepeatBuff
} from "../../../effects/ops/stat.js";
import { handleKeyword } from "../../../effects/ops/keyword/unified.js";
import { handleCost } from "../../../effects/ops/cost/unified.js";
import { handleSpellboost } from "../../../effects/ops/spellboost/unified.js";
import { handleCounter } from "../../../effects/ops/counter/unified.js";
import { applyAttacksPerTurn } from "../../../effects/attacks.js";
import { getTargetingContext } from "../context.js";

// import { BuffEffect } from "../../../../core/types.js";

export function registerBuffEffects() {

    // Stats - unified stat handler covers give +X/+Y, set stats, buff_hand_*, combo_repeat, etc
    registerOp("stat", (eff, ctx) => {
        if (handleStat(eff, ctx.owner, ctx.sourceCard, ctx.queue, ctx.context as any) === "pending") return "pending";
    });
    // Legacy combo_repeat_buff was removed - now handled by:
    // { op: "stat", mode: "combo_repeat", target: "...", attack: N, defense: N }

    registerOp("attacks_per_turn", (eff, ctx) => applyAttacksPerTurn(eff as any, ctx.sourceCard));

    // ==========================================================================
    // UNIFIED KEYWORD - replaces keyword, remove_keyword, remove_abilities, grant_trigger
    // ==========================================================================
    registerOp("keyword", (eff, ctx) => {
        const tCtx = getTargetingContext(ctx);
        const merged = { ...tCtx, sourceCard: ctx.sourceCard, targets: (ctx.context as any)?.targets };
        const opCtx = { ...merged, isTargetedEffect: !!(eff.select || eff.select_count) };

        let targets = (merged.targets && merged.targets.length > 0 && !eff.target)
            ? merged.targets
            : getPool(eff.target || "", ctx.owner, ctx.sourceCard, eff.condition, opCtx);

        // Apply filters if specified
        if ((eff as any).filters) {
            const filters = (eff as any).filters;
            targets = targets.filter((c: any) => {
                if (filters.class && c.class !== filters.class) return false;
                if (filters.type && c.type?.toLowerCase() !== String(filters.type).toLowerCase()) return false;
                if (filters.tribe && (!Array.isArray(c.tribes) || !c.tribes.includes(filters.tribe))) return false;
                return true;
            });
        }

        // Apply exclude_self if specified
        if ((eff as any).exclude_self && ctx.sourceCard) {
            targets = targets.filter((c: any) => c.uid !== ctx.sourceCard?.uid);
        }

        const res = handleKeyword(eff as any, {
            owner: ctx.owner,
            sourceCard: ctx.sourceCard,
            targets,
            effectsQueue: ctx.queue,
            isTargetedEffect: opCtx.isTargetedEffect
        });

        if (res.kind === "request_target") {
            setPendingTarget({
                ...res.request,
                targets: []
            });
            highlightSelectable(res.request.pool);
            return "pending";
        }
    });

    // ==========================================================================
    // UNIFIED COST - replaces 6 legacy cost ops
    // ==========================================================================
    registerOp("cost", (eff, ctx) => {
        handleCost(eff as any, ctx.owner, ctx.sourceCard, ctx.context);
    });

    // ==========================================================================
    // UNIFIED COUNTER - replaces add_counter, reduce_countdown, increase_countdown
    // ==========================================================================
    registerOp("counter", (eff, ctx) => {
        handleCounter(eff as any, { owner: ctx.owner, source: ctx.sourceCard });
    });

    // ==========================================================================
    // UNIFIED SPELLBOOST - replaces 5 legacy spellboost ops
    // Note: spellboost_transform is now handled by unified transform op with zone: "hand"
    // ==========================================================================
    registerOp("spellboost", (eff, ctx) => {
        handleSpellboost(eff as any, ctx.owner, ctx.sourceCard, ctx.context);
    });

}

import { BUFF_OPS } from "./buffsOps.js";
export const OPS = BUFF_OPS;

import { registerOp } from "../registry.js";
import { enqueueManyFront } from "../queue.js";
import { handleDamage } from "../../../effects/ops/damage/unified.js";
import { handleDestroy } from "../../../effects/ops/destroy/index.js";
import { handleBanish } from "../../../effects/ops/banish/index.js";
import { handleRestore } from "../../../effects/ops/restore/index.js";
import {
    handleLeaderBarrierOp, handleSetMaxHP, handleSetLeaderMaxDamageCap,
    handleModifyLeaderDamageReceived
} from "../../../effects/leader.js";
import { cleanupDead } from "../../cleanup.js";
import { logEvent } from "../../../../core/logger.js";



export function registerCombatEffects() {
    // Unified damage handler - the single canonical damage op
    // All damage effects use "op": "damage" with distribution/amount_source fields
    registerOp("damage", (eff, ctx) => {
        const result = handleDamage(eff, ctx.owner, ctx.sourceCard, ctx.queue, ctx.context as any);
        if (result === "pending") return "pending";
    });

    // Unified destroy handler - the single canonical destroy op
    // All destroy effects use "op": "destroy" with distribution/scope fields
    registerOp("destroy", (eff, ctx) => {
        const destroyCtx = { ...(ctx.context as object || {}), sourceCard: ctx.sourceCard, owner: ctx.owner };
        const result = handleDestroy(eff, ctx.owner, ctx.queue, destroyCtx);
        if (result === "pending") return "pending";
    });

    // Unified banish handler - the single canonical banish op
    // All banish effects use "op": "banish" with distribution/scope fields
    registerOp("banish", (eff, ctx) => {
        const banishCtx = { ...(ctx.context as object || {}), sourceCard: ctx.sourceCard, owner: ctx.owner };
        const result = handleBanish(eff, ctx.owner, ctx.queue, banishCtx);
        if (result === "pending") return "pending";
    });

    // Unified restore handler - the single canonical restore/heal op
    // All restore effects use "op": "restore" with target/amount_source fields
    registerOp("restore", (eff, ctx) => {
        const restoreCtx = { ...(ctx.context as object || {}), sourceCard: ctx.sourceCard, owner: ctx.owner };
        handleRestore(eff, ctx.owner, ctx.queue, restoreCtx);

        // Crest processing for leader heal
        if (eff.target === "leader" || eff.target === "allies" || !eff.target) {
            void import("../../../effects/crest.js").then(({ processCrestEvent }) => {
                const targetOwner = (eff.player || "self") === "self" ? ctx.owner : (ctx.owner === "blue" ? "red" : "blue");
                const fx = processCrestEvent(targetOwner, "heal_leader");
                if (fx.length) enqueueManyFront(ctx, fx);
            });
        }
    });

    registerOp("clash_damage", (eff, ctx) => {
        const attacker = (ctx.context as any)?.attacker;
        const defender = (ctx.context as any)?.defender;
        if (!attacker || !defender || !ctx.sourceCard) return;

        // Opponent is whoever is NOT the source card
        const opponent = ctx.sourceCard.uid === attacker.uid ? defender : attacker;

        void import('../../barrier.js').then(({ dealDamage }) => {
            dealDamage(opponent, Number(eff.amount || 0));
            cleanupDead();
        });
    });
    // ========================================================================
    // LEADER STATE EFFECTS - Now handled by unified ops with target: ally:leader / enemy:leader
    // - stat op: set defense (max HP)
    // - keyword op: Barrier, MaxDamageCap, Vulnerable
    // ========================================================================

}

import { COMBAT_OPS } from "./combatOps.js";
export const OPS = COMBAT_OPS;

import { registerOp, EffectCtx } from "../registry.js";
import { handleSelect, TargetContext } from "../../targeting.js";
import { runEffects } from "../index.js";
import { handleMode } from "../../../effects/ops/mode.js";
import { handleModeBonus } from "../../../effects/ops/misc.js";
import { handleRepeatEffect } from "../../../effects/repeat.js";
import { handleEvolve } from "../../../effects/ops/evolve/unified.js";
import { handleGate } from "../../../effects/gates/unified.js";
import { Effect, CardInstance } from "../../../../core/types.js";
import { logEvent } from "../../../../core/logger.js";

const stub = (_op: string) => (_eff: Effect, _ctx: EffectCtx) => {
    // console.warn(`[Stub] Op '${op}' called but not implemented.`);
};

export function registerMiscEffects() {
    registerOp("mode", handleMode as any);
    registerOp("mode_bonus", handleModeBonus as any);



    // Generic Op: Select (Delegates to targeting.ts implementation)
    registerOp("select", (eff, ctx) => {
        // Ensure ctx.context has a runner if missing (targeting expects one for auto-resolve)
        const tCtx: TargetContext = ctx.context || {};
        if (!tCtx.runner) {
            tCtx.runner = runEffects;
        }

        const res = handleSelect(eff, ctx.owner, ctx.sourceCard, ctx.queue, tCtx);
        if (res === "pending") return "pending";
    });


    // ==========================================================================
    // UNIFIED EVOLVE - replaces 8 legacy evolve_* ops
    // ==========================================================================
    registerOp("evolve", (eff, ctx) => {
        handleEvolve(eff as any, ctx.owner, ctx.sourceCard, ctx.context);
    });

    // ==========================================================================
    // UNIFIED GATE - replaces 17 legacy *_gate ops
    // ==========================================================================
    registerOp("gate", (eff, ctx) => {
        handleGate(eff as any, ctx.owner, ctx.sourceCard, ctx.queue);
    });

    // combo_add is now handled by counter op with key: "combo"

    registerOp("repeat_effect", (eff, ctx) => handleRepeatEffect(eff, ctx.owner, ctx.sourceCard, ctx.queue));

    registerOp("set_deckout_victory", stub("set_deckout_victory"));

    // Skybound
    registerOp("boost_skybound_art_hand", (eff, ctx) => {
        const amt = Number(eff.amount ?? 1);
        // Dynamic import to avoid cycles if any (though skybound.ts is leaf)
        import("../../../effects/skybound.js").then(({ incrementSkyboundArt }) => {
            incrementSkyboundArt(ctx.owner, amt);
        }).catch(e => console.error("Failed to load skybound module:", e));
    });
}

import { registerOp } from "../registry.js";
import { state } from "../../../../core/gameState.js";
import { handleDraw } from "../../../effects/ops/draw/index.js";
import { handleDiscard } from "../../../effects/hand.js";
import { handleReplaceDeck } from "../../../effects/deck.js";
import { handleSetCostLastDrawn } from "../../../effects/ops/misc.js";
import { consumeEarthSigils } from "../../../effects/ops/earth.js";
import { hasNecromancy, spendShadows } from "../../../../helpers/necromancy.js";
import { isOverflow } from "../../../../helpers/overflow.js";
import { handleFuse } from "../../../effects/ops/fuse/unified.js";
import { startFortifierFuse } from "../../../effects/ops/fuse/fuse.js";
import { handleCrest } from "../../../effects/ops/crest/unified.js";
import { logEvent } from "../../../../core/logger.js";
import { getAdapter, getTargetingContext } from "../context.js";
import { enqueueManyFront } from "../queue.js";
import { addMaxPP } from "../../../pp.js";
import { Effect, Player } from "../../../../core/types.js";

const doLog = (event: string, payload: any) => logEvent(event, payload);

// ========================================================================
// UNIFIED PP/EP HANDLERS
// ========================================================================

type PPAction = "gain_max" | "recover";
type EPAction = "recover";

function handlePP(eff: Effect & { action?: PPAction }, owner: Player) {
    const action = eff.action;
    if (!action) {
        console.warn("pp op: action field is mandatory (gain_max, recover)");
        return;
    }

    const targetIsBlue = (eff.player || "self") === "self" ? owner === "blue" : owner !== "blue";

    switch (action) {
        case "gain_max": {
            const amt = (eff.amount || 1) as number;
            addMaxPP(targetIsBlue ? "blue" : "red", amt, { cap: 10, recalcNow: true });
            break;
        }
        case "recover": {
            const cur = targetIsBlue ? state.bluePP : state.redPP;
            const max = targetIsBlue ? state.blueMaxPP : state.redMaxPP;

            let amt;
            if (typeof eff.amount === "string" && eff.amount.toLowerCase() === "currentmaxpp") {
                amt = Math.max(0, max - cur);
            } else {
                amt = parseInt(String(eff.amount)) || 0;
            }

            const next = Math.min(max, cur + amt);
            if (targetIsBlue) state.bluePP = next;
            else state.redPP = next;
            logEvent("recoverPP", { owner: targetIsBlue ? "blue" : "red", amount: amt });
            break;
        }
        default:
            console.warn(`pp op: unknown action ${action}`);
    }
}

function handleEP(eff: Effect & { action?: EPAction }, owner: Player) {
    const action = eff.action;
    if (!action) {
        console.warn("ep op: action field is mandatory (recover)");
        return;
    }

    const isBlue = (eff.player || "self") === "self" ? owner === "blue" : owner !== "blue";
    const MAX_EP = 2;

    switch (action) {
        case "recover": {
            const amt = parseInt(String(eff.amount)) || 0;
            if (isBlue) {
                state.blueEvoCharges = Math.min(MAX_EP, (state.blueEvoCharges || 0) + amt);
            } else {
                state.redEvoCharges = Math.min(MAX_EP, (state.redEvoCharges || 0) + amt);
            }
            logEvent("recoverEP", { owner: isBlue ? "blue" : "red", amount: amt });
            break;
        }
        default:
            console.warn(`ep op: unknown action ${action}`);
    }
}

export function registerResourceEffects() {

    // ========================================================================
    // UNIFIED PP - replaces gain_max_pp, recover_pp
    // action: "gain_max" = increase max PP
    // action: "recover" = restore current PP
    // ========================================================================
    registerOp("pp", (eff, ctx) => handlePP(eff as any, ctx.owner));

    // ========================================================================
    // UNIFIED EP - replaces recover_ep
    // action: "recover" = restore evolution points
    // ========================================================================
    registerOp("ep", (eff, ctx) => handleEP(eff as any, ctx.owner));

    // Shadows / Necromancy
    registerOp("add_shadows", (eff, ctx) => {
        const amt = (eff.amount || 1) as number;
        if (ctx.owner === "blue") state.blueShadows = (state.blueShadows || 0) + amt;
        else state.redShadows = (state.redShadows || 0) + amt;
    });

    // Earth Rite
    registerOp("earth_rite", (eff, ctx) => {
        if (consumeEarthSigils(ctx.owner, (eff.amount as number) || 1)) {
            if (eff.effects) enqueueManyFront(ctx, eff.effects);
        }
    });

    // UNIFIED DRAW - single entry point for all draw operations
    // source: "deck" (default) = draw from deck
    // source: "named" = generate card by name (replaces add_to_hand)
    // source: "copy" = copy selected card (replaces add_selected_copy_to_hand)
    registerOp("draw", (eff, ctx) => handleDraw(eff, ctx.owner));

    // ========================================================================
    // UNIFIED DISCARD - replaces discard_select_hand, discard_all_except_named
    // mode: "select" = select cards to discard (default)
    // mode: "except_named" = discard all except named cards
    // ========================================================================
    registerOp("discard", (eff, ctx) => {
        if (handleDiscard(eff, ctx.owner, ctx.queue) === "pending") return "pending";
    });

    // Legacy transform_in_hand and transform_random_spell_in_hand
    // are now handled by unified transform op with zone: "hand"

    // ========================================================================
    // UNIFIED DECK - replaces replace_deck, replace_deck_with_set_minus,
    // halve_deck_cost, reduce_deck_followers_cost
    // set_cost_last_drawn is now handled by cost op with target: "last_drawn"
    // ========================================================================
    registerOp("deck", (eff, ctx) => {
        void import("../../../effects/deck.js").then(({ handleDeck }) => {
            handleDeck(eff, ctx.owner, { adapter: getAdapter(ctx) });
        });
    });

    // ========================================================================
    // UNIFIED CREST - replaces gain_crest, crest_add_counter, crest_pay_counter, destroy_crest, crest_advance_countdown
    // ========================================================================
    registerOp("crest", (eff, ctx) => {
        handleCrest(eff as any, { owner: ctx.owner });
    });

    // ==========================================================================
    // UNIFIED FUSE - replaces fuse_start, start_fuse_from_card, fuse_finalize_*
    // ==========================================================================
    registerOp("fuse", (eff, ctx) => {
        const result = handleFuse(eff as any, ctx.owner, ctx.sourceCard, ctx.queue, ctx.context);
        if (result === "pending") return "pending";
        doLog("fuse", { owner: ctx.owner, action: eff.action, type: (eff as any).type });
    });

    // start_fortifier_fuse is now handled by fuse op with type: "fortifier"
}

