// ========================================================================
// UNIFIED DECK HANDLER - routes by action field
// ========================================================================
export function handleDeck(eff: any, owner: Player, context: any = {}): void | "pending" {
    const action = eff.action || "replace";

    switch (action) {
        case "replace":
            // from_set: Replace deck with all cards from a set (one copy each)
            if (eff.from_set) {
                void replaceDeckFromSet(owner, eff.from_set, eff.exclude).then(() => {
                    context.adapter?.render?.();
                });
            }
            // cards: Explicit card list with counts
            else if (eff.cards) {
                handleReplaceDeckFromList(owner, eff.cards);
            }
            break;

        case "cost":
            void import("./cost.js").then(({ handleHalveDeckCost, reduceDeckFollowersCost }) => {
                if (eff.mode === "halve") {
                    handleHalveDeckCost(owner);
                } else if (eff.filter === "follower") {
                    const amt = parseInt(eff.amount ?? 1) || 1;
                    reduceDeckFollowersCost(owner, amt);
                }
            });
            break;

        default:
            console.warn(`[deck] Unknown action: ${action}`);
    }
}

// ========================================================================
// REPLACE FROM SET
// Replace deck with all cards from a set (one copy each), optionally excluding cards by name
// 
// Example:
//   { "op": "deck", "action": "replace", "from_set": "10003_heirs-of-the-omen", "exclude": ["Card Name"] }
// ========================================================================
async function replaceDeckFromSet(owner: Player, setId: string, exclude?: string[]): Promise<void> {
    const setFile = `/cards/sets/${setId}.json`;
    const excludeSet = new Set((exclude || []).map(s => String(s)));

    const res = await fetch(setFile, { cache: "no-cache" });
    if (!res.ok) {
        console.warn(`[deck] Set not found: ${setId} (${setFile})`);
        return;
    }
    const cards = await res.json();

    const deck = owner === "blue" ? state.blueDeck : state.redDeck;
    deck.length = 0;

    for (const base of Array.isArray(cards) ? cards : []) {
        if (!base?.name) continue;
        if (excludeSet.has(String(base.name))) continue;
        const copy = JSON.parse(JSON.stringify(base));
        copy.uid = state.rng.makeUid();
        deck.push(copy);
    }

    shuffleInPlace(deck);
    logEvent("deckReplaceFromSet", {
        owner,
        set: setId,
        count: deck.length,
        excluded: excludeSet.size,
    });
}

// ========================================================================
// REPLACE FROM LIST
// Replace deck with explicit list of cards by name with optional counts
// 
// Example:
//   { "op": "deck", "action": "replace", "cards": [{ "name": "Fairy", "count": 3 }] }
// ========================================================================
function handleReplaceDeckFromList(owner: Player, cards: { name: string, count?: number }[]) {
    const deck = owner === "blue" ? state.blueDeck : state.redDeck;
    deck.length = 0;

    for (const { name, count } of cards) {
        const cardData = getCardDetails(name);
        if (cardData) {
            for (let i = 0; i < (count || 1); i++) {
                const copy = JSON.parse(JSON.stringify(cardData));
                copy.uid = state.rng.makeUid();
                deck.push(copy);
            }
        }
    }

    shuffleInPlace(deck);
    logEvent("deckReplace", { owner, count: deck.length });
}

// Legacy export alias (deprecated - use handleDeck instead)
export const handleReplaceDeck = handleReplaceDeckFromList;

// src/logic/effects/gates/unified.ts

import { state } from "../../../core/gameState.js";
import { hasNecromancy, spendShadows } from "../../../helpers/necromancy.js";
import { isOverflow } from "../../../helpers/overflow.js";
import { logEvent } from "../../../core/logger.js";
import { Player, CardInstance, Effect } from "../../../core/types.js";
import { UnifiedGateSpec, GateContext, normalizeToGateSpec } from "./types.js";

/**
 * Unified gate handler - evaluates any gate condition and queues effects.
 * Replaces 17 legacy gate handlers.
 */
export function handleGate(
    eff: Effect,
    owner: Player,
    sourceCard: CardInstance | null,
    effectsQueue: Effect[]
): "done" {
    const spec = normalizeToGateSpec(eff);
    const passed = evaluateCondition(spec, owner, sourceCard);

    logEvent("gate", {
        condition: spec.condition,
        passed,
        owner,
        card: sourceCard?.name
    });

    const next = passed ? (spec.effects || []) : (spec.else_effects || []);
    if (next.length && Array.isArray(effectsQueue)) {
        effectsQueue.unshift(...next);
    }

    return "done";
}

/**
 * Evaluates a gate condition and returns true if it passes.
 */
function evaluateCondition(
    spec: UnifiedGateSpec,
    owner: Player,
    sourceCard: CardInstance | null
): boolean {
    switch (spec.condition) {
        // =====================================================================
        // RESOURCE GATES
        // =====================================================================
        case "necromancy": {
            const need = Math.max(1, spec.cost || 1);
            if (hasNecromancy(owner, need)) {
                spendShadows(owner, need);
                logEvent("necromancySpend", { owner, cost: need });
                return true;
            }
            logEvent("necromancyBlocked", { owner, need });
            return false;
        }

        case "overflow":
            return isOverflow(owner);

        // =====================================================================
        // PP GATES
        // =====================================================================
        case "max_pp": {
            const need = spec.at_least ?? 10;
            const currentMax = owner === "blue" ? state.blueMaxPP : state.redMaxPP;
            return currentMax >= need;
        }

        case "both_max_pp": {
            const need = spec.at_least ?? 10;
            return state.blueMaxPP >= need && state.redMaxPP >= need;
        }

        // =====================================================================
        // COUNT GATES
        // =====================================================================
        case "combo": {
            const need = spec.count ?? 1;
            const plays = owner === "blue" ? (state.bluePlaysThisTurn || 0) : (state.redPlaysThisTurn || 0);
            return plays >= need;
        }

        case "rally": {
            const need = spec.count ?? 1;
            const rally = owner === "blue" ? state.blueRally : state.redRally;
            return rally >= need;
        }

        case "hand_count": {
            const need = spec.count ?? 1;
            const hand = owner === "blue" ? state.blueHand : state.redHand;
            return hand.length >= need;
        }

        case "amulet_count": {
            const need = spec.count ?? 1;
            const board = owner === "blue" ? state.blueBoard : state.redBoard;
            const amuletCount = (board || []).filter(c => c.type === "Amulet").length;
            return amuletCount >= need;
        }

        case "spellboost_count": {
            // Check the source card's spellboost count against threshold
            if (!sourceCard) return false;
            const count = sourceCard.keywordState?.spellboostCount ?? sourceCard.spellboostCount ?? 0;
            const need = spec.count ?? 1;
            return count >= need;
        }

        // =====================================================================
        // EVOLUTION GATES
        // =====================================================================
        case "evolved_self":
            return !!(sourceCard && sourceCard.hasEvolved);

        case "super_evolved_self":
            return !!(sourceCard && sourceCard.type === "Follower" && sourceCard.evoType === "super");

        case "evolved_allied": {
            const board = owner === "blue" ? state.blueBoard : state.redBoard;
            return board.some(c => c.type === "Follower" && (c.hasEvolved || c.evoType === "super"));
        }

        case "super_evolved_allied": {
            const board = owner === "blue" ? state.blueBoard : state.redBoard;
            return board.some(c => c.type === "Follower" && c.evoType === "super");
        }

        case "super_evo_unlocked":
            // Blue unlocks at turn 7, red at turn 6
            return owner === "blue" ? state.roundCount >= 7 : state.roundCount >= 6;

        // =====================================================================
        // BOARD/CARD GATES
        // =====================================================================
        case "board_name": {
            const want = String(spec.name || "").trim();
            if (!want) return false;
            const myBoard = owner === "blue" ? state.blueBoard : state.redBoard;
            return (myBoard || []).some(c => String(c?.name) === want);
        }

        case "self_cost": {
            if (!sourceCard) return false;
            const effCost = getEffectiveCost(sourceCard);
            const targetCost = spec.cost ?? 0;
            return effCost === targetCost;
        }

        // =====================================================================
        // SPECIAL GATES
        // =====================================================================
        case "skybound_art": {
            const witnesses = (sourceCard as any)?.skyboundArtEvolvesWitnessed || 0;
            const gauge = (state.roundCount || 1) + witnesses;
            const req = spec.requirement ?? 10;
            console.log(`[Gate] Skybound Art: Turn=${state.roundCount} Witnessed=${witnesses} Gauge=${gauge} Req=${req}`);
            return gauge >= req;
        }

        case "no_ally_attacked": {
            // Check global flag first
            if (owner === "blue" ? !!state.blueAnyAllyAttackedThisTurn : !!state.redAnyAllyAttackedThisTurn) {
                return false;
            }
            const board = owner === "blue" ? state.blueBoard : state.redBoard;
            return !(board || []).some(c => {
                if (!c || c.type !== "Follower") return false;
                const used = (c.attacks_used_this_turn ?? 0) > 0;
                const legacy = !!c.hasAttacked;
                const perTurn = Number.isFinite(c.attacks_per_turn) ? c.attacks_per_turn! : 1;
                const left = Number.isFinite(c.attacks_left) ? c.attacks_left! : perTurn;
                const spent = left < perTurn;
                return used || legacy || spent;
            });
        }

        case "highlander": {
            const deck = owner === "blue" ? state.blueDeck : state.redDeck;
            if (!deck || deck.length <= 1) return true;
            const seenNames = new Set<string>();
            for (const card of deck) {
                if (seenNames.has(card.name)) {
                    logEvent("highlanderCheck", { owner, result: "fail", name: card.name });
                    return false;
                }
                seenNames.add(card.name);
            }
            logEvent("highlanderCheck", { owner, result: "pass" });
            return true;
        }

        default:
            console.warn(`[Gate] Unknown condition: ${spec.condition}`);
            return false;
    }
}

function getEffectiveCost(card: CardInstance): number {
    if (Number.isFinite(card.effectiveCost)) return card.effectiveCost!;
    const base = parseInt(card?.cost as string, 10) || 0;
    const mod = parseInt((card as any)?.cost_mod, 10) || 0;
    return base + mod;
}

// src/logic/effects/hand.ts
import { state } from "../../core/gameState.js";
import { getCardDetails } from "../../data/cardDatabase.js";
// import { render } from "../../ui/render.js";
import { highlightSelectable } from "../core/targeting.js";
import { setPendingTarget } from "../core/pendingTarget/index.js";

import { logEvent } from "../../core/logger.js";
import { CardInstance, Player, Effect } from "../../core/types.js";

// ========================================================================
// UNIFIED DISCARD HANDLER - routes by mode field
// ========================================================================

export type DiscardMode = "select" | "except_named";

export function handleDiscard(
    eff: Effect & { mode?: DiscardMode },
    owner: Player,
    resumeEffects: Effect[] = []
): void | "pending" {
    const mode = (eff.mode || "select") as DiscardMode;

    switch (mode) {
        case "except_named":
            handleDiscardAllExceptNamed(eff, owner);
            return;

        case "select":
        default:
            return handleDiscardSelectHand(eff, owner, resumeEffects);
    }
}

// ========================================================================
// INTERNAL HANDLERS
// ========================================================================

export function handleDiscardAllExceptNamed(eff: Effect, owner: Player) {
    const names = ((eff as any).names || (eff as any).name || []).map(String);
    const keepSet = new Set(names);
    const hand = owner === "blue" ? state.blueHand : state.redHand;
    const grave = owner === "blue" ? state.blueGraveyard : state.redGraveyard;

    let discarded = 0;

    for (let i = hand.length - 1; i >= 0; i--) {
        const c = hand[i];
        if (c && keepSet.has(String(c.name))) continue; // keep
        const removed = hand.splice(i, 1)[0];
        if (removed) {
            grave.push(removed); // discard
            discarded++;
        }
    }

    if (discarded > 0) {
        logEvent("discard", { owner, count: discarded });
        if (owner === "blue") state.blueShadows += discarded;
        else state.redShadows += discarded;
    }
}

/**
 * Start a "select N cards from hand to discard" interaction.
 * Returns "pending" when it needs user input so runEffects pauses.
 */
export function handleDiscardSelectHand(eff: Effect, owner: Player, resumeEffects: Effect[] = []) {
    const n = Math.max(0, parseInt(eff.count as any ?? 1, 10));
    const hand = owner === "blue" ? state.blueHand : state.redHand;
    if (n <= 0 || hand.length === 0) return;

    const selectCount = Math.min(n, hand.length);
    const pool = [...hand];

    setPendingTarget({
        op: "discard_select_hand",
        eff: { ...eff, select_count: selectCount },
        owner,
        sourceCard: null,
        pool,
        selectCount,
        targets: [],
        resumeEffects,
    } as any);

    // mark with the correct flag and render
    highlightSelectable(pool); // sets __uiSelectable + render()
    return "pending";
}

// Legacy handleTransformInHand was removed - now handled by unified transform op with zone: "hand"

// src/logic/effects/ops/evolve/types.ts

import { Effect, Player, CardInstance } from "../../../../core/types.js";

/**
 * Target for an evolve operation.
 */
export type EvolveTarget =
    | "self"           // Source card
    | "selected"       // Player-selected target (from context)
    | "last_summoned"  // Cards in state.lastSummoned
    | "all_allies"     // All allied unevolved followers
    | string;          // Named card filter

/**
 * Mode for evolution.
 */
export type EvolveMode = "normal" | "super";

/**
 * Unified specification for all evolve operations.
 * Replaces 8 legacy evolve ops.
 */
export interface UnifiedEvolveSpec {
    op: "evolve";

    /** Target for evolution (defaults to "selected") */
    target?: EvolveTarget;

    /** Evolution mode: normal (+2/+2) or super (+3/+3) */
    mode?: EvolveMode;

    /** Named card filter for all_allies targeting */
    name?: string;

    /** Whether to spend evolution point (default: false for effect-triggered evolutions) */
    spend_point?: boolean;
}

/**
 * Normalizes any evolve effect (including legacy formats) into UnifiedEvolveSpec.
 */
export function normalizeToEvolveSpec(eff: Effect): UnifiedEvolveSpec {
    const legacyOp = eff.op as string;

    const spec: UnifiedEvolveSpec = {
        op: "evolve",
    };

    // Map legacy op names to target/mode
    switch (legacyOp) {
        case "evolve_self":
            spec.target = "self";
            break;
        case "super_evolve_self":
            spec.target = "self";
            spec.mode = "super";
            break;
        case "evolve":
            spec.target = (eff as any).target || "selected";
            break;
        case "evolve_last_summoned":
            spec.target = "last_summoned";
            break;
        case "evolve_all_unevolved_allies":
            spec.target = "all_allies";
            break;
        case "super_evolve_all_unevolved_allies":
            spec.target = "all_allies";
            spec.mode = "super";
            break;
        case "evolve_all_allies_named":
            spec.target = "all_allies";
            spec.name = (eff as any).name;
            break;
        case "super_evolve_ally":
            spec.target = "selected";
            spec.mode = "super";
            break;
        default:
            // Already unified format
            spec.target = (eff as any).target || "selected";
            spec.mode = (eff as any).mode;
            spec.name = (eff as any).name;
            spec.spend_point = (eff as any).spend_point;
    }

    // Copy remaining fields
    if ((eff as any).mode && !spec.mode) spec.mode = (eff as any).mode;
    if ((eff as any).spend_point !== undefined) spec.spend_point = (eff as any).spend_point;

    return spec;
}

