// src/logic/effects/ops/fuse/unified.ts
// Unified fuse operation handler

import { Player, CardInstance } from "../../../../core/types.js";
import { FuseOp } from "./types.js";

// Import existing handlers
import {
    opStartFuseFromCard,
    fuse_finalize_generic,
} from "./fuse.js";

import {
    fuse_finalize_alpha,
    fuse_finalize_gear_multi,
    fuse_finalize_fortifier,
    startFortifierFuse,
} from "./fuse.artifact.js";

import {
    fuse_finalize_gardens_allure,
} from "./fuse.forest.js";

import {
    fuse_finalize_loot,
} from "./fuse.loot.js";

/**
 * Unified fuse handler
 * 
 * Routes based on action field:
 * - action: "start" → Opens fuse partner selection
 * - action: "finalize" → Routes to type-specific finalizer
 * - type: "fortifier" (no action) → Starts fortifier fuse flow
 */
export function handleFuse(
    eff: FuseOp,
    owner: Player,
    sourceCard: CardInstance | null,
    _effectsQueue: any[],
    context: any = {}
): string | void {
    const action = eff.action;
    const type = eff.type;

    // === TYPE-BASED INITIATION (no action) ===
    // For specific fuse types that have their own initiation flow
    if (!action && type === "fortifier" && sourceCard) {
        return startFortifierFuse(owner, sourceCard);
    }

    if (!action) {
        console.warn(`[fuse] Missing action field - must be "start" or "finalize". Effect:`, eff);
        return "done";
    }

    // === ACTION: START ===
    if (action === "start") {
        return opStartFuseFromCard(eff, owner);
    }

    // === ACTION: FINALIZE ===
    if (action === "finalize") {
        const type = eff.type || "generic";
        const initiatorUid = eff.initiator_uid || "";
        const partners = context.targets || [];

        switch (type) {
            case "generic":
                const partner = partners[0];
                if (partner) {
                    fuse_finalize_generic(owner, initiatorUid, partner, eff.result);
                }
                break;

            case "fortifier":
                fuse_finalize_fortifier(owner, initiatorUid, partners);
                break;

            case "alpha":
                fuse_finalize_alpha(owner, initiatorUid, partners);
                break;

            case "gear_multi":
                fuse_finalize_gear_multi(owner, initiatorUid, partners, eff.result_name || "");
                break;

            case "loot":
                fuse_finalize_loot(owner, initiatorUid, partners);
                break;

            case "gardens_allure":
                fuse_finalize_gardens_allure(owner, initiatorUid, partners);
                break;

            default:
                console.warn(`[fuse] Unknown finalize type: "${type}"`);
        }

        return "done";
    }

    console.warn(`[fuse] Unknown action: "${action}"`);
    return "done";
}

// src/logic/effects/ops/mode.ts
import { state } from "../../../core/gameState.js";
import { hasEarthSigils, consumeEarthSigils } from "./earth.js";
import { adapter } from "../../../core/adapter.js";
// import { spellboostHand } from "./spellboost.js"; // Unused
// import { handleDrawFiltered } from "./draw.js"; // Unused
// import { handleReanimate } from "./reanimate.js"; // Unused
import { runEffects } from "../../core/effects/index.js";
import { fireTrigger } from "../../core/triggers.js";
import { logEvent } from "../../../core/logger.js";
import { doAction, appendStep } from "../../../core/history.js";
import { Effect, Player, CardInstance } from "../../../core/types.js";

// Import types if needed, or define locally if specific to mode
// ChooseEffect? 
// For now, I will typify 'eff' as any to avoid breaking, but better to use Effect and safe access.
// Actually, I should use Effect & { options?: any[], select_count?: number, unique?: boolean }
// But for now, safe property access is enough.

import { EffectCtx } from "../../core/effects/registry.js";

export function handleMode(eff: Effect, ctx: EffectCtx) {
    const { owner, sourceCard, queue: effectsQueue } = ctx;

    // console.group("[CHOICE DEBUG] Handling choose effect (multi-pick)");
    const options = Array.isArray((eff as any)?.options) ? (eff as any).options : [];
    const baseSelect = Math.max(1, parseInt((eff as any)?.select_count ?? 1));
    const bonus = owner === "blue" ? (state.blueModeBonus || 0) : (state.redModeBonus || 0);
    // Clamp to available options
    const selectCount = Math.min(options.length, baseSelect + bonus);
    logEvent("chooseOpen", { owner, options: options.length, selectCount });
    const unique = (eff as any)?.unique !== false; // default true

    // Filter options by resource gates (e.g., Earth Rite) like before
    // All options remain available; Earth Rite cost will be attempted on pick
    const available = options;
    if (available.length === 0) {
        // console.warn("No options configured");
        // console.groupEnd();
        return;
    }

    // ==== AI / Headless path (no modal) ====
    const isAIMode = () => {
        // Your spectator sets these during AI searches/turns (see AlphaVanillaSpectator) :contentReference[oaicite:3]{index=3}
        // If you later run bots without the spectator, you can flip HEADLESS yourself before resolving effects.
        return !!(globalThis && ((globalThis as any).HEADLESS || (globalThis as any).AI_SUPPRESS_RENDER));
    };

    // Tiny heuristic: favor immediate board impact & resources; slight penalty if ER cost can’t be paid.
    const scoreOption = (opt: any) => {
        let s = 0;
        const ops = Array.isArray(opt?.effects) ? opt.effects : [];
        for (const e of ops) {
            const op = String(e?.op || "").toLowerCase();
            if (op === "damage" || op === "damage_all" || op === "damage_random" ||
                op === "destroy" || op === "destroy_all" || op === "destroy_random") s += 6;
            if (op === "summon_named" || op === "reanimate") s += 5;
            if (op === "stat") s += 3;
            if (op === "draw" || op === "draw_filtered" || op === "add_to_hand") s += 3;
            if (op === "recover_pp" || op === "gain_max_pp" || op === "restore_pp") s += 2;
            if (op === "leader_barrier" || op === "restore_defense" || op === "heal") s += 2;
            // small bias for effects mentioning enemy in target
            if (typeof e?.target === "string" && /enemy/i.test(e.target)) s += 1;
        }
        // Earth Rite affordability nudge
        if (opt?.requires?.earth_rite) {
            const need = parseInt(opt.requires.earth_rite) || 1;
            const canPay = hasEarthSigils ? hasEarthSigils(owner, need) : true;
            if (!canPay) s -= 4;
            else s += 1;
        }
        return s;
    };

    if (isAIMode()) {
        const picked: any[] = [];
        const paidByOpt = new Map();
        const pool = available.slice();

        while (picked.length < selectCount && pool.length) {
            // Enforce uniqueness if requested
            const candidates = unique ? pool.filter((o: any) => !picked.includes(o)) : pool;
            if (!candidates.length) break;
            // Choose highest scoring remaining option
            candidates.sort((a: any, b: any) => scoreOption(b) - scoreOption(a));
            const chosen = candidates[0];
            // Attempt to pay ER (if required); if fail, we still pick but will fizzle later (matches human flow)
            let paid = true;
            if (chosen?.requires?.earth_rite) {
                const need = parseInt(chosen.requires.earth_rite) || 1;
                paid = consumeEarthSigils(owner, need);
            }
            picked.push(chosen);
            paidByOpt.set(chosen, paid);
            // remove from pool once chosen
            const i = pool.indexOf(chosen);
            if (i >= 0) pool.splice(i, 1);
        }

        // Record in parent action as a step, then execute inline (no nested action)
        appendStep("AI Choice", {
            owner,
            picks: picked.map(p => p?.label || p?.name || "(opt)"),
            requiresER: picked.map(p => !!p?.requires?.earth_rite)
        });
        logEvent("chooseFinalize", { owner, picked: picked.length, ai: true });
        for (let i = 0; i < picked.length; i++) {
            // Removed try/catch empty block. fireTrigger should range.
            fireTrigger("select_mode", owner, { sourceCard: sourceCard || null });
        }
        const combined: Effect[] = [];
        for (const opt of picked) {
            const fizzled = (opt?.requires?.earth_rite && paidByOpt.get(opt) === false);
            if (fizzled) continue;
            if (Array.isArray(opt.effects) && opt.effects.length) combined.push(...opt.effects);
        }
        if (combined.length) {
            runEffects(combined, owner, sourceCard);
        }
        if (effectsQueue && effectsQueue.length) {
            runEffects(effectsQueue, owner, sourceCard);
        } else {
            if (!(globalThis as any).AI_SUPPRESS_RENDER) adapter.render();
        }
        // console.groupEnd();
        return "done";
    }
    // ==== /AI path ====

    // Keep direct references to chosen options for identity comparison
    const picked: any[] = [];
    // Track resource-payment outcome per option (e.g., Earth Rite)
    const paidByOpt = new Map();

    const finalize = () => {
        // One undo step for the whole choice confirmation
        doAction(
            "Confirm Choice",
            () => {
                logEvent("chooseFinalize", { owner, picked: picked.length });

                // Make Faith crest deterministic & undoable: increment once per mode actually chosen
                for (let i = 0; i < picked.length; i++) {
                    fireTrigger("select_mode", owner, { sourceCard: sourceCard || null });
                }

                // Flatten effects of all picked options in pick order
                const combined: Effect[] = [];
                for (const opt of picked) {
                    const fizzled = (opt?.requires?.earth_rite && paidByOpt.get(opt) === false);
                    if (fizzled) continue; // nothing happens
                    if (Array.isArray(opt.effects) && opt.effects.length) combined.push(...opt.effects);
                }

                if (combined.length) {
                    runEffects([...combined], owner, sourceCard);
                }

                if (effectsQueue && effectsQueue.length) {
                    runEffects([...effectsQueue], owner, sourceCard);
                } else {
                    adapter.render();
                }
                // console.groupEnd();
            },
            { owner, picks: picked.map(p => p?.label || p?.name || "(opt)") },
            { autoRender: false }
        );
    };

    const pickOnce = (pool: any[]) => {
        // Build the pool for this round (remove duplicates if unique)
        const roundPool = unique
            ? pool.filter(opt => !picked.includes(opt))
            : pool.slice();

        if (roundPool.length === 0) {
            // console.warn("No options left to pick.");
            finalize();
            return;
        }

        adapter.showChoiceModal(roundPool, (selectedIndex: number) => {
            const selected = roundPool[selectedIndex];
            logEvent("choosePick", { owner, index: selectedIndex, requiresER: !!selected?.requires?.earth_rite });
            if (!selected) { finalize(); return; }

            // Try to pay Earth Rite; if it fails, we still proceed and fizzle later.
            let paid = true;
            if (selected.requires?.earth_rite) {
                paid = consumeEarthSigils(owner, selected.requires.earth_rite);
                if (!paid) {
                    // console.warn("Earth Rite cost not paid – effect fizzles");
                    logEvent("earthRiteFizzle", { owner, option: selected.label });
                }
            }

            // Record selection and payment result
            picked.push(selected);
            paidByOpt.set(selected, paid);

            if (picked.length < selectCount) {
                pickOnce(pool);
            } else {
                finalize();
            }
        });
    };

    // Start first round
    pickOnce(available);
    return "pending"; // Return pending to pause effect chain while modal is shown
}

// src/logic/effects/ops/spellboost.ts
import { state } from "../../../core/gameState.js";
import { adapter } from "../../../core/adapter.js";
import { getCardDetails } from "../../../data/cardDatabase.js";

import { logEvent } from "../../../core/logger.js";
import { Player, CardInstance } from "../../../core/types.js";

// CIRCULAR DEPENDENCY FIX:
let runEffects: any = null;
export function registerRunEffectsForSpellboost(fn: any) {
    runEffects = fn;
}


/* ------------------------ helpers ------------------------ */

function incSB(card: CardInstance) {
    if (!card) return;
    if (!card.keywordState) card.keywordState = {};
    const hasKS = typeof card.keywordState.spellboostCount === "number";
    const val = (hasKS ? card.keywordState.spellboostCount! : (card.spellboostCount || 0)) + 1;

    card.keywordState.spellboostCount = val;
    card.spellboostCount = val; // Legacy sync for UI/Values
}

function getSpellboostKeyword(card: CardInstance) {
    if (!Array.isArray(card?.keywords)) return null;
    for (const k of card.keywords) {
        if (typeof k === "string" && k.toLowerCase() === "spellboost") return { name: "Spellboost" };
        if (typeof k === "object" && k?.name?.toLowerCase() === "spellboost") return k;
    }
    return null;
}

function normTimes(x: any) {
    if (typeof x === "number" && Number.isFinite(x) && x > 0) return x;
    if (x && typeof x === "object") {
        const n = parseInt(x.times ?? x.count ?? 1, 10);
        return Number.isFinite(n) && n > 0 ? n : 1;
    }
    return 1;
}

// Legacy transformSelfInHand was removed - now handled by:
// { op: "gate", condition: "spellboost_count", count: N, effects: [{ op: "transform", zone: "self", into: "..." }] }

/**
 * Handle all Spellboost keyword effects for ONE in-hand card.
 * All effects are passed to runEffects - gate conditions handle thresholds.
 */
function handleSpellboostKeywordEffects(owner: Player, c: CardInstance) {
    const kws = Array.isArray(c.keywords) ? c.keywords : [];
    for (const kw of kws) {
        if ((kw as any)?.name !== "Spellboost" || !Array.isArray((kw as any).effects)) continue;

        // All spellboost effects are now handled by the generic effect system
        // Gate conditions (e.g. spellboost_count) will check thresholds automatically
        for (const effect of (kw as any).effects) {
            runEffects([effect], owner, c);
        }
    }
}


export function handleSetSpellboostCount(eff: any, sourceCard: CardInstance) {
    if (!sourceCard) return;
    const val = parseInt(eff.amount ?? 0, 10) || 0;
    if (!sourceCard.keywordState) sourceCard.keywordState = {};
    sourceCard.keywordState.spellboostCount = val;
    sourceCard.spellboostCount = val; // Legacy sync

    // If setting to 0, visually clear it (UI might check for >0 or existing property)
    // Re-rendering happens periodically
}

/* ------------------------ main ------------------------ */

/**
 * spellboostHand
 * Supports both signatures:
 * - spellboostHand(owner, times = 1, targetCard = null)
 * - spellboostHand(owner, targetCard, times = 1)
 */
export function spellboostHand(owner: Player, times: any = 1, targetCard: any = null) {
    if (owner !== "blue" && owner !== "red") return;

    // Signature normalization
    // If the second argument looks like a card (has uid), treat it as targetCard
    if (targetCard === null && times && typeof times === "object" && "uid" in times) {
        targetCard = times;
        times = 1;
    }
    // If third arg is actually a number, accept it as times
    if (typeof targetCard === "number" && Number.isFinite(targetCard)) {
        times = targetCard;
        targetCard = null;
    }

    const t = normTimes(times);
    const hand = owner === "blue" ? state.blueHand : state.redHand;




    for (let i = 0; i < t; i++) {
        // --- Single-card spellboost path ---
        if (targetCard) {
            const kw = getSpellboostKeyword(targetCard);
            if (kw) {
                // increment counter first
                incSB(targetCard);

                // optional cost reduction (only if keyword specifies)
                if (Object.prototype.hasOwnProperty.call(kw, "reduceCostBy")) {
                    const reduceBy = Number.isFinite(kw.reduceCostBy) ? kw.reduceCostBy : 0;
                    const minCost = Number.isFinite(kw.minCost) ? kw.minCost : 0;

                    targetCard.base_cost = targetCard.base_cost ?? (parseInt(String(targetCard.cost), 10) || 0);
                    const prev = targetCard.spellboostCostCount || 0;
                    const next = prev + reduceBy;
                    targetCard.spellboostCostCount = next;

                    const newCost = Math.max(minCost ?? 0, Number(targetCard.base_cost ?? 0) - next);
                    if (Number.isFinite(newCost)) targetCard.cost = newCost;
                }
                logEvent("spellboost", { owner, card: targetCard.name, uid: targetCard.uid, count: targetCard.keywordState?.spellboostCount, newCost: targetCard.cost });

                // run in-hand effects for THIS card
                handleSpellboostKeywordEffects(owner, targetCard);
            }
        } else {
            // --- Whole-hand spellboost path ---
            for (const c of hand) {
                const kw = getSpellboostKeyword(c);
                if (!kw) continue;

                // increment counter first
                incSB(c);

                // optional cost reduction (opt-in per keyword)
                if (Object.prototype.hasOwnProperty.call(kw, "reduceCostBy")) {
                    const reduceBy = Number.isFinite(kw.reduceCostBy) ? kw.reduceCostBy : 0;
                    const minCost = Number.isFinite(kw.minCost) ? kw.minCost : 0;

                    c.base_cost = c.base_cost ?? (parseInt(String(c.cost), 10) || 0);
                    const prev = c.spellboostCostCount || 0;
                    const next = prev + reduceBy;
                    c.spellboostCostCount = next;

                    const newCost = Math.max(minCost ?? 0, Number(c.base_cost ?? 0) - next);
                    if (Number.isFinite(newCost)) c.cost = newCost;
                }
                logEvent("spellboost", { owner, card: c.name, uid: c.uid, count: c.keywordState?.spellboostCount, newCost: c.cost });

                // run in-hand effects for this card
                handleSpellboostKeywordEffects(owner, c);
            }
        }
    }

    adapter.render();
}

